// ------------------------------------------------------------------
// Main Component
// ------------------------------------------------------------------
const RiskAssessment: React.FC<RiskAssessmentProps> = ({
  backgroundColor = "#f0f2f5",
  transparentBackground = false,
  durationInSeconds = 7,
  primaryGradientStart = "#ff4d4f",
  primaryGradientEnd = "#ff7a45",
  successColor = "#52c41a",
  textColor = "#111111",
  scoreText = "Security score",
  buttonText = "Generate report",
  toastMessage = "Download your report",
  statsValues = ["4", "787", "0.6.12", "SHA256", "200 Runs", "Apr 13, 2026"],
  riskLabels = ["Critical", "High", "Medium", "Low", "Informative"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Constants optimized for 16:9 Responsiveness
  const cardWidth = Math.min(width * 0.85, 1600);
  const cardHeight = Math.min(height * 0.8, 860);

  // Timeline Keyframes
  const CARD_INTRO = 0;
  const CIRCLE_START = 20;
  const GRID_START = 30;
  const ROWS_START = 45;
  const CURSOR_START = 90;
  const CLICK_DOWN = 135;
  const CLICK_UP = 138;
  const TOAST_START = 150;

  // 1. Card Intro Animation
  const cardIntroProgress = spring({ frame: frame - CARD_INTRO, fps, config: { damping: 14 } });
  const cardY = interpolate(cardIntroProgress, [0, 1], [60, 0]);
  const cardOpacity = cardIntroProgress;

  // 2. Circle Progress Animation
  const circleProgress = spring({ frame: frame - CIRCLE_START, fps, config: { damping: 15 } });
  const scoreValue = interpolate(circleProgress, [0, 1], [0, 93]);
  const circleRadius = 160;
  const circleCircumference = 2 * Math.PI * circleRadius;
  const circleOffset = circleCircumference - (circleCircumference * scoreValue) / 100;

  // 3. Grid Data Setup
  const statData = [
    { id: "issue", icon: <BugIcon />, label: "Issue count", format: "large" },
    { id: "code", icon: <CodeIcon />, label: "Lines of code", format: "large" },
    { id: "version", icon: <HexIcon />, format: "small" },
    { id: "sha", icon: <FileTextIcon />, format: "small" },
    { id: "runs", icon: <GearIcon />, format: "small" },
    { id: "date", icon: <CalendarIcon />, format: "small" },
  ];

  // 4. Rows Setup
  const rowsData = [
    { label: riskLabels[0] || "Critical", count: 0, color: "#a8071a", progress: 0 },
    { label: riskLabels[1] || "High", count: 0, color: "#f5222d", progress: 0 },
    { label: riskLabels[2] || "Medium", count: 1, color: "#fa8c16", progress: 0.5 },
    { label: riskLabels[3] || "Low", count: 1, color: "#fadb14", progress: 0.5 },
    { label: riskLabels[4] || "Informative", count: 2, color: "#d9d9d9", progress: 0 },
  ];

  // 5. Cursor & Interaction Animations
  const startX = width + 200;
  const startY = height + 200;
  
  // Dynamic targeting for 16:9 layout's top-right header button
  const targetX = (width + cardWidth) / 2 - 190;
  const targetY = (height - cardHeight) / 2 + 100;

  const cursorX = interpolate(frame, [CURSOR_START, CURSOR_START + 40], [startX, targetX], {
    easing: Easing.bezier(0.4, 0, 0.2, 1),
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const cursorY = interpolate(frame, [CURSOR_START, CURSOR_START + 40], [startY, targetY], {
    easing: Easing.bezier(0.4, 0, 0.2, 1),
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const buttonScaleDown = interpolate(frame, [CLICK_DOWN, CLICK_DOWN + 3], [1, 0.95], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const buttonScaleUp = interpolate(frame, [CLICK_UP, CLICK_UP + 3], [0, 0.05], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const buttonScaleVal = buttonScaleDown + buttonScaleUp;

  const cursorScaleDown = interpolate(frame, [CLICK_DOWN, CLICK_DOWN + 3], [1, 0.85], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const cursorScaleUp = interpolate(frame, [CLICK_UP, CLICK_UP + 3], [0, 0.15], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const cursorScaleVal = cursorScaleDown + cursorScaleUp;

  const isHovered = frame >= CURSOR_START + 35;
  const buttonFilter = isHovered ? "brightness(1.05)" : "brightness(1)";

  // 6. Toast Popup Animation
  const toastSpring = spring({ frame: frame - TOAST_START, fps, config: { damping: 14 } });
  const toastY = interpolate(toastSpring, [0, 1], [60, 0]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
      }}
    >
      {/* Main Card */}
      <div
        style={{
          width: cardWidth,
          height: cardHeight,
          backgroundColor: "white",
          borderRadius: 48,
          boxShadow: "0 32px 64px rgba(0,0,0,0.08), 0 12px 24px rgba(0,0,0,0.04)",
          padding: "60px 80px",
          display: "flex",
          flexDirection: "column",
          position: "relative",
          opacity: cardOpacity,
          transform: `translateY(${cardY}px)`,
          transition: "none",
        }}
      >
        {/* Header Section (Horizontal layout for 16:9) */}
        <div style={{ display: "flex", flexDirection: "row", justifyContent: "space-between", alignItems: "center", marginBottom: 60, transition: "none", width: "100%" }}>
          <div style={{ fontSize: 64, fontWeight: 800, color: textColor, letterSpacing: "-0.02em", transition: "none" }}>
            Risk Assessment
          </div>
          <div style={{ display: "flex", gap: 24, transition: "none" }}>
            <div
              style={{
                padding: "20px 36px",
                border: "2px solid #e5e5e5",
                borderRadius: 20,
                display: "flex",
                alignItems: "center",
                gap: 12,
                fontWeight: 600,
                fontSize: 22,
                color: "#333",
                transition: "none",
              }}
            >
              <ScanIcon /> Rescan
            </div>
            <div
              style={{
                padding: "20px 40px",
                background: `linear-gradient(90deg, ${primaryGradientStart}, ${primaryGradientEnd})`,
                color: "white",
                borderRadius: 20,
                display: "flex",
                alignItems: "center",
                gap: 12,
                fontWeight: 600,
                fontSize: 22,
                transform: `scale(${buttonScaleVal})`,
                filter: buttonFilter,
                position: "relative",
                overflow: "hidden",
                boxShadow: frame >= CLICK_DOWN ? "none" : `0 16px 32px ${primaryGradientStart}40`,
                transition: "none",
              }}
            >
              <PlusIcon /> {buttonText}
              {/* Ripple Effect */}
              {frame >= CLICK_UP && (
                <div
                  style={{
                    position: "absolute",
                    left: "50%",
                    top: "50%",
                    width: 240,
                    height: 240,
                    marginLeft: -120,
                    marginTop: -120,
                    borderRadius: "50%",
                    backgroundColor: "rgba(255,255,255,0.4)",
                    transform: `scale(${interpolate(frame, [CLICK_UP, CLICK_UP + 15], [0, 2], { extrapolateRight: "clamp" })})`,
                    opacity: interpolate(frame, [CLICK_UP, CLICK_UP + 15], [0.8, 0], { extrapolateRight: "clamp" }),
                    transition: "none",
                    pointerEvents: "none",
                  }}
                />
              )}
            </div>
          </div>
        </div>

        {/* Body Section (3-Column layout for 16:9) */}
        <div style={{ display: "flex", flexDirection: "row", flex: 1, gap: 60, width: "100%", alignItems: "center", transition: "none" }}>
          
          {/* Column 1: Progress Circle */}
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", minWidth: 400, transition: "none" }}>
            <div style={{ position: "relative", width: 360, height: 360, transition: "none" }}>
              <svg width={360} height={360} viewBox="0 0 360 360" style={{ transition: "none" }}>
                <circle cx={180} cy={180} r={circleRadius} fill="none" stroke="#f0f0f0" strokeWidth={28} />
                <circle
                  cx={180}
                  cy={180}
                  r={circleRadius}
                  fill="none"
                  stroke={successColor}
                  strokeWidth={28}
                  strokeDasharray={circleCircumference}
                  strokeDashoffset={circleOffset}
                  strokeLinecap="round"
                  style={{ transform: "rotate(-90deg)", transformOrigin: "center", transition: "none" }}
                />
              </svg>
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: 84,
                  fontWeight: 700,
                  color: successColor,
                  transition: "none",
                }}
              >
                {Math.round(scoreValue)}%
              </div>
            </div>
            <div style={{ fontSize: 32, fontWeight: 700, color: textColor, marginTop: 32, transition: "none" }}>
              {scoreText}
            </div>
          </div>

          {/* Column 2: Stats Grid */}
          <div style={{ display: "flex", flexDirection: "column", flex: 1.2, justifyContent: "center", transition: "none" }}>
            <div style={{ width: "100%", display: "grid", gridTemplateColumns: "1fr 1fr", gap: "40px 24px", transition: "none" }}>
              {statData.map((item, index) => {
                const itemSpring = spring({ frame: frame - GRID_START - index * 3, fps, config: { damping: 12 } });
                const itemY = interpolate(itemSpring, [0, 1], [20, 0]);
                const rawVal = statsValues[index] || "";
                const parsedVal = parseFloat(rawVal);
                const isAnimatableNum = (index === 0 || index === 1) && !isNaN(parsedVal);
                const displayVal = isAnimatableNum
                  ? Math.round(interpolate(itemSpring, [0, 1], [0, parsedVal]))
                  : rawVal;

                if (item.format === "large") {
                  return (
                    <div key={item.id} style={{ display: "flex", flexDirection: "column", opacity: itemSpring, transform: `translateY(${itemY}px)`, transition: "none" }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 20, transition: "none" }}>
                        <div style={{ width: 56, height: 56, display: "flex", alignItems: "center", justifyContent: "center", color: "#111", transition: "none" }}>
                          {item.icon}
                        </div>
                        <div style={{ fontSize: 64, fontWeight: 700, color: textColor, lineHeight: 1, transition: "none" }}>
                          {displayVal}
                        </div>
                      </div>
                      <div style={{ color: "#888", fontSize: 24, marginTop: 16, marginLeft: 76, fontWeight: 500, transition: "none" }}>
                        {item.label}
                      </div>
                    </div>
                  );
                }

                return (
                  <div key={item.id} style={{ display: "flex", alignItems: "center", gap: 16, fontSize: 28, fontWeight: 600, color: "#444", opacity: itemSpring, transform: `translateY(${itemY}px)`, transition: "none" }}>
                    <div style={{ width: 48, height: 48, display: "flex", alignItems: "center", justifyContent: "center", color: "#111", transition: "none" }}>
                      {item.icon}
                    </div>
                    {displayVal}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Column 3: Risk Rows */}
          <div style={{ display: "flex", flexDirection: "column", flex: 1.2, justifyContent: "center", borderLeft: "2px solid #f2f2f2", paddingLeft: 60, height: "100%", transition: "none" }}>
            {rowsData.map((r, i) => {
              const rowSpring = spring({ frame: frame - ROWS_START - i * 4, fps, config: { damping: 14 } });
              const rowX = interpolate(rowSpring, [0, 1], [-20, 0]);
              const animatedProgress = r.progress * Math.min(1, rowSpring);
              const animatedCount = Math.round(interpolate(rowSpring, [0, 1], [0, r.count]));

              return (
                <div key={r.label} style={{ display: "flex", alignItems: "center", gap: 24, marginBottom: 32, opacity: rowSpring, transform: `translateX(${rowX}px)`, transition: "none" }}>
                  <div style={{ width: 20, height: 20, borderRadius: "50%", backgroundColor: r.color, flexShrink: 0, transition: "none" }} />
                  <div style={{ width: 40, fontSize: 28, fontWeight: 700, textAlign: "right", color: textColor, flexShrink: 0, transition: "none" }}>
                    {animatedCount}
                  </div>
                  <div style={{ width: 160, fontSize: 24, color: "#666", fontWeight: 500, flexShrink: 0, transition: "none" }}>
                    {r.label}
                  </div>
                  <div style={{ flex: 1, height: 12, backgroundColor: "#f0f0f0", borderRadius: 8, position: "relative", overflow: "hidden", transition: "none" }}>
                    <div
                      style={{
                        position: "absolute",
                        top: 0,
                        left: 0,
                        height: "100%",
                        width: `${animatedProgress * 100}%`,
                        backgroundColor: r.color,
                        borderRadius: 8,
                        transition: "none",
                      }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* Toast Popup */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.1,
          left: "50%",
          transform: `translateX(-50%) translateY(${toastY}px)`,
          opacity: toastSpring,
          backgroundColor: "#1a1a1a",
          color: "white",
          padding: "24px 48px",
          borderRadius: 60,
          fontSize: 28,
          fontWeight: 600,
          display: "flex",
          alignItems: "center",
          gap: 20,
          boxShadow: "0 16px 48px rgba(0,0,0,0.25)",
          transition: "none",
        }}
      >
        <div style={{ color: successColor, display: "flex", transition: "none" }}>
          <CheckCircleIcon />
        </div>
        {toastMessage}
      </div>

      {/* Cursor */}
      {frame >= CURSOR_START && (
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            transform: `translate(${cursorX}px, ${cursorY}px) scale(${cursorScaleVal})`,
            transformOrigin: "top left",
            pointerEvents: "none",
            zIndex: 100,
            transition: "none",
          }}
        >
          <CursorArrow />
        </div>
      )}
    </AbsoluteFill>
  );
};

export default RiskAssessment;